const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("AC-015 the test throws its own error", async ({ page }) => {
  await page.goto("index.html");
  throw new Error("the output\n\nexpect(the output) to show 5");
  await expect(page.locator("#out")).toHaveText("");
});

